<?php
require_once __DIR__ . '/includes/bootstrap.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $name = trim($_POST['name'] ?? ''); $email = strtolower(trim($_POST['email'] ?? '')); $password = $_POST['password'] ?? '';
    if (strlen($name) < 2 || !filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($password) < 8) { flash('Enter your name, a valid email, and a password of at least 8 characters.'); header('Location: ' . app_url('/register.php')); exit; }
    try { $stmt = $pdo->prepare('INSERT INTO users (name, email, password_hash) VALUES (?, ?, ?)'); $stmt->execute([$name, $email, password_hash($password, PASSWORD_DEFAULT)]); session_regenerate_id(true); $_SESSION['user'] = ['id' => (int) $pdo->lastInsertId(), 'name' => $name, 'email' => $email, 'role' => 'customer']; flash('Welcome to Rally — your account is ready.'); header('Location: ' . app_url('/')); exit; }
    catch (PDOException $exception) { if ($exception->getCode() === '23000') flash('An account with that email already exists.'); else throw $exception; }
}
$title = 'Create account — Rally'; require __DIR__ . '/includes/header.php';
?>
